#!/usr/bin/env python3
"""NU-20261102-A12-R1 · Nivel 1 (14 capítulos). Todas las cifras de valoración salen de VALORACION_A12_EN_REVISION.json,
construido a su vez desde la captura de la hoja; los hechos de negocio salen del 20-F 2025, del 6-K de estados del 2T26 y del comunicado del 2T26."""
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parent.parent
REV = 'NU-20261102-A12-R1'
V = json.loads((ROOT / f'candidatos/valoraciones/{REV}/VALORACION_A12_EN_REVISION.json').read_text())
SUP = V['supuestosModeloA']; SD = V['sensibilidadDCF']; ESC = V['escenarios']
H = {h['nombre']: h for h in V['valorEsperado']['historias']}
MET = {m['nombre']: m for m in V['metodos']}
PROY = V['nivel2ProyeccionBase']; CAP = SUP['controlCapitalRegulatorio']
ALT = SD['alternativaCapital']; INV = SD['dcfInverso']


def n(x, d=0):
    return f'{x:,.{d}f}'.replace(',', 'X').replace('.', ',').replace('X', '.')
usd = lambda x, d=2: 'US$' + n(x, d)
pc = lambda x, d=1: n(x * 100, d) + ' %'
P = lambda t: f'<p>{t}</p>'
base, cons, opt, disr = ESC['base'], ESC['conservador'], ESC['optimista'], ESC['disrupcion']
precio = V['precio']; mos = V['precioMOS']; prom = V['valorEsperado']['valor']
ke_b = SUP['ke']['Base']; ke_c = SUP['ke']['Conservador']; ke_d = SUP['ke']['Disrupcion']
pe = MET['P/E']['valorHoy']; pbv = MET['P/BV']['valorHoy']; pfcfe = MET['P/FCFE']['valorHoy']

CAPS = []


def cap(titulo, *partes):
    CAPS.append((titulo, ''.join(partes)))


cap('1. Tesis y resumen ejecutivo',
    P(f'Nu Holdings (Nubank) es el banco digital más grande de América Latina por clientes: 139 millones a junio de 2026, con casi 118 millones en Brasil, 15,8 millones en México y más de 5 millones en Colombia. '
      f'La tesis del Método JMR A-1.2 es que su economía por cliente (un costo de servir y de gastos generales por cliente activo que la compañía estima cerca de 85 % inferior al de los bancos tradicionales en Brasil, una tasa de actividad mensual de 83,5 % y un ingreso medio por cliente activo de unos US$17 al mes) '
      f'financia un crecimiento de utilidades que, descontado al costo del patrimonio, vale <strong>{usd(base)} por acción</strong> en la historia Base frente a un cierre de {usd(precio)} el 30 de octubre de 2026. '
      f'El precio máximo de compra con margen de seguridad del 35 % es {usd(mos)}, por debajo del precio de mercado: el mercado no ofrece margen de seguridad hoy según este método, aunque sí un valor intrínseco superior al precio.'),
    P(f'Las cuatro historias valen {usd(cons)} (Conservadora), {usd(base)} (Base), {usd(opt)} (Optimista) y {usd(disr)} (Disrupción, presentada aparte). El promedio ponderado ordinario de las tres primeras es {usd(prom)}. '
      'Por tratarse de una institución financiera, la valoración principal es un descuento de flujos al accionista (FCFE) a diez años al costo del patrimonio (Ke), no el FCFF industrial: los depósitos, el fondeo y las pérdidas de crédito son la materia prima del negocio y no pueden tratarse como deuda ni como gasto financiero ajeno a la operación.'),
    P(f'Lo que descuenta el precio: con los flujos de la historia Base, el precio de {usd(precio)} equivale a un Ke de {pc(INV["keImplicito"])}, unos {n((INV["keImplicito"]-ke_b)*100,1)} puntos por encima del {pc(ke_b, 2)} que resulta de la metodología Damodaran. '
      f'Dicho de otro modo, con el Ke de la casa el mercado descuenta el {pc(INV["utilidadRelativaImplicita"], 0)} de la utilidad Base. La brecha entre ambas lecturas es el debate central del caso y está reflejada en la matriz Ke × g del Nivel 2.'),
    P('Tres reservas condicionan la lectura y se desarrollan en los capítulos 6, 8 y 10: (i) la utilidad del primer semestre de 2026 contiene US$991 millones de beneficio de impuesto diferido, por lo que las historias normalizan el margen neto a una tasa efectiva cercana al 26 %; '
      f'(ii) el capital se mide con utilidad sobre ROE y no con activos ponderados por riesgo por entidad, y la comparación con un APR aproximado sugiere que la Base retiene más patrimonio del que exige el regulador (si el patrimonio se mantuviera en 40 % del APR, el valor sería {usd(ALT["valor"][3])}); '
      '(iii) el Ke de una acción brasileña medido en dólares es el supuesto más sensible y el más expuesto al ciclo político y de tasas. Este expediente está en revisión: no ha sido auditado económicamente.'))

cap('2. Modelo de negocio, segmentos y monetización',
    P('Nu inició operaciones en 2013 y lanzó en 2014 en Brasil una tarjeta de crédito Mastercard sin cuota anual, diseñada para operar íntegramente desde una aplicación. Desde esa cuña de crédito construyó una plataforma de servicios financieros: cuenta de depósitos y pagos (incluidas transferencias Pix), '
      'préstamos personales con y sin garantía (nómina para pensionados y empleados públicos, respaldo en el FGTS), seguros, inversiones, una operadora móvil virtual (NuCel, con Claro) y cuentas multimoneda. La expansión internacional se concentra en México y Colombia.'),
    P('La contabilidad NIIF consolida un solo segmento operativo: el director ejecutivo revisa el estado de resultados consolidado y no asigna recursos por línea. Por eso la unidad económica útil es el cliente. En el comunicado del 2T26 la utilidad bruta gerencial se reparte así: crédito 41 %, comisiones 25 % y float (rendimiento del dinero de los depósitos) 34 %, '
      'las tres crecieron en dólares. Esa mezcla importa para el riesgo: el 41 % que proviene del crédito soporta el costo de crédito esperado; el float depende de las tasas; las comisiones dependen de la actividad transaccional.'),
    P('La cartera de crédito total llegó a US$39,4 mil millones en el 2T26 (+37 % interanual): tarjetas por US$26 mil millones, préstamos sin garantía por US$10,3 mil millones y con garantía por US$3,1 mil millones. Los depósitos sumaron US$45,3 mil millones (+18 % interanual): US$36,4 mil millones en Brasil, US$5,7 mil millones en México y US$3,3 mil millones en Colombia. '
      'El costo de los depósitos se mantuvo en 88 % de la tasa interbancaria, tres puntos porcentuales menos que un año antes. Al cierre de 2025, 92,5 % de los depósitos eran exigibles a la vista, lo que hace del fondeo una fuente barata pero de liquidez exigente.'),
    P('El margen financiero (NIM) fue 22,9 % en el 2T26 y el NIM ajustado por riesgo 12,4 %; el costo de crédito del trimestre fue de unos US$1.700 millones. En términos NIIF, el ingreso total del trimestre fue US$5.513 millones y la pérdida de crédito esperada US$1.482 millones. '
      'El índice de eficiencia subió a 19,5 % (17,6 % en el 1T26 y 21,3 % en el 2T25) por gasto inmobiliario y de mercadeo trasladado al segundo trimestre y por la inversión internacional.'))

cap('3. Industria, mercado direccionable y crecimiento orgánico',
    P('Nu opera en tres mercados con grados de madurez distintos. En Brasil, el banco ya sirve a la mayor parte del segmento de mercado masivo y compite por la relación bancaria primaria y por el segmento de ingresos altos con productos como Ultravioleta y, desde julio de 2026, Croma para clientes «Super Core». '
      'El comunicado del 2T26 indica que la actividad mensual en Brasil superó por primera vez el 86 %, lo que deja poco espacio de crecimiento por simple adición de clientes y desplaza la palanca hacia la profundidad: más productos por cliente, más crédito por cliente y mayor captación de depósitos.'),
    P('México es la gran opción de crecimiento: Nu alcanza al 16,5 % de la población adulta, una penetración comparable a la de Brasil en 2020 según la compañía, con un ingreso por cliente activo de US$12,3 frente a US$5,6 que tenía Brasil en la misma etapa. En agosto de 2026 lanzó su banco en México, con lo que pasa de ser una fintech de crédito a una institución completa, '
      'con una razón de préstamos a depósitos de apenas 35 % en ese país. Colombia, con más de 5 millones de clientes, es una apuesta más pequeña (US$3,3 mil millones de depósitos) con capital regulatorio de US$179,7 millones y un índice de 15,3 % frente a un mínimo de 10,5 %.'),
    P('El mercado direccionable se aproxima por adultos bancarizables y por el potencial de crédito al consumo; el Método JMR no estima una participación de mercado exacta porque la información verificable de este expediente (20-F 2025 y 6-K del 2T26) no la entrega de forma comparable entre países. '
      'La proyección Base no depende de esa cifra: crece los ingresos a un ritmo que decae de 30 % en el primer año a 6 % en el décimo, un camino consistente con la desaceleración de la adición de clientes y con una convergencia del ingreso por cliente hacia niveles de madurez.'))

cap('4. Ventajas competitivas y competencia',
    P('La ventaja competitiva de Nu se apoya en tres elementos documentados: costo de servir bajo (sin sucursales, con un costo de servir y gastos generales por cliente activo que la compañía estima en el 20-F cerca de 85 % inferiores a los de los bancos tradicionales de Brasil; con inteligencia artificial resolviendo más del 60 % de las conversaciones de soporte en Brasil con calidad igual o superior a la humana, según la compañía), '
      'datos propios de más de una década de historial transaccional de más de 100 millones de clientes que alimentan su modelo de comportamiento financiero (NuFormer, hoy en producción en tarjetas de Brasil y México y en préstamos sin garantía de Brasil), y fondeo de depósitos a un costo de 88 % de la tasa interbancaria.'),
    P('La compañía sostiene que los clientes cuya relación bancaria primaria es Nu muestran una morosidad cercana a la mitad del promedio de la cartera y que la morosidad a 90 días mejoró en cada banda de ingresos desde julio de 2025, mientras la de los bancos pares en los mismos segmentos empeoraba. Es una afirmación de la gerencia, no auditada; la hoja de supuestos la trata como evidencia de calidad, no como prueba.'),
    P('Siguiendo la regla de moat del Método JMR (ganar sobre el costo del capital de forma sostenida, ventaja identificable, ventaja que no se desvanece de forma visible), Nu cumple las dos primeras: el ROE sobre patrimonio medio fue 18,2 % en 2023, 28,1 % en 2024 y 30,3 % en 2025 (utilidad de la controladora de US$1.031, US$1.972 y US$2.869 millones), siempre por encima del costo del patrimonio. '
      'La tercera no se cumple todavía de manera visible, pero el ROE de 2025 incluye un efecto de impuestos que no es permanente y la tasa de morosidad a 90 días sube en el 2T26 por efecto estacional y expansión intencional hacia segmentos de mayor riesgo y rendimiento. Por eso el ROE terminal de la Base (16 %) es un valor intermedio: por encima del costo del patrimonio, muy por debajo del ROE actual.'),
    P('Entre los competidores, la hoja de pares usa Itaú (ITUB), Bradesco (BBD), PagBank (PAGS), Banco Inter (INTR) y StoneCo (STNE) como referencias de mercado para los múltiplos. Los bancos tradicionales tienen acceso a la clientela de mayores ingresos y un costo de fondeo propio; los pares digitales compiten en la misma población que Nu. '
      'Ninguno de ellos tiene la escala de clientes de Nu, pero tampoco se puede concluir una ventaja permanente: la regulación de Pix y Open Finance en Brasil, de la que el 20-F da cuenta, reduce los costos de cambio y facilita el traslado de saldos.'))

cap('5. Ciclos empresariales, macroeconómicos y de mercado',
    P('<strong>Ciclo de vida (Damodaran).</strong> Nu pasa de crecimiento alto a crecimiento maduro. Los ingresos NIIF crecieron 68 % en 2023, 43 % en 2024 y 37 % en 2025 y 51 % en el primer semestre de 2026 frente al mismo período de 2025; la utilidad de la controladora pasó de US$1.031 millones (2023) a US$2.869 millones (2025). '
      'La reinversión es patrimonial (crecer exige capital regulatorio) y no de activos fijos: propiedad, planta y equipo suman solo US$51 millones. La previa de probabilidades del Método para la etapa de crecimiento alto es 40 % Base, 22,5 % Conservadora, 22,5 % Optimista y 15 % Disrupción, y no se movió: ningún indicador cruzó un umbral escrito.'),
    P('<strong>Ciclo macroeconómico y monetario observado al 30-oct-2026.</strong> La tasa Selic del Banco Central de Brasil estaba en 13,75 % tras el recorte de 25 puntos básicos de septiembre, según la prensa especializada; tras la reelección presidencial del 25 de octubre, la prensa informó de una caída de las acciones brasileñas y de que el mercado pasó a descontar con alta probabilidad un alza de tasas en la reunión del Copom del 4 de noviembre. '
      'Son fuentes secundarias que deben verificarse; el real cotizó entre 5,35 y 5,38 por dólar entre el 28 y el 30 de octubre según Yahoo Finance. El Treasury a 10 años cerró en 4,94 % el 30 de octubre y la prima madura de Damodaran es 3,70 %.'),
    P('<strong>Ciclo de crédito y de mercado (Marks).</strong> Para un banco de consumo el ciclo se manifiesta primero en el costo de crédito: la morosidad temprana (15-90 días) mejoró 16 puntos básicos a 4,8 % en el 2T26 mayormente por estacionalidad, mientras la de más de 90 días subió 35 puntos básicos a 6,9 % por la migración de la morosidad del primer trimestre. '
      'La gerencia reconoce ampliaciones intencionales de riesgo. La expansión del crédito sin garantía (US$10,3 mil millones) en un entorno de tasas altas es la señal que más debe vigilarse. En el mercado, las acciones de pares brasileños cotizan hoy entre 3 y 9 veces utilidades con ROE de 14 a 34 %: el mercado local prima el riesgo político y fiscal.'),
    P('<strong>Canal causal.</strong> Tasas altas elevan el rendimiento del float y de la cartera, pero también el costo de crédito y el costo del patrimonio; un real débil reduce el valor en dólares de utilidades en reales; una desaceleración eleva morosidad con rezago de uno a dos trimestres. '
      'Señales que cambiarían el juicio: morosidad de más de 90 días por encima de 8 % durante dos trimestres, costo de depósitos por encima de 95 % del interbancario, un ROE trimestral por debajo de 25 % y un capital total regulatorio de Brasil por debajo de 13 %. A favor de la tesis: ARPAC de México superior a US$12 sostenido y un índice de eficiencia por debajo de 20 % con crecimiento de cartera mayor a 30 %.'))

cap('6. Estados financieros, rentabilidad y calidad de resultados',
    P(f'Los ingresos NIIF fueron US$8.029 millones en 2023, US$11.517 millones en 2024 y US$15.775 millones en 2025, y US$19.340 millones en los doce meses a junio de 2026. La utilidad bruta (después de gasto de intereses, gasto transaccional y pérdida de crédito esperada) fue US$3.491, US$5.253 y US$6.625 millones en 2023-2025. '
      'La utilidad de la controladora fue US$1.031, US$1.972 y US$2.869 millones, y US$3.607 millones en los doce meses a junio de 2026. El patrimonio de la controladora pasó de US$6.406 millones (2023) a US$13.250 millones (junio de 2026), con US$500 millones de recompras en el semestre.'),
    P('<strong>Calidad de la utilidad.</strong> En el primer semestre de 2026 la utilidad antes de impuestos fue US$2.191 millones y el impuesto contable US$258 millones (tasa efectiva 11,8 %, frente a 28,7 % en el primer semestre de 2025). La nota de impuestos del 6-K desglosa un impuesto corriente de US$1.249 millones y un beneficio de impuesto diferido de US$991 millones (en el primer semestre de 2025 el diferido fue un gasto de US$40 millones). '
      'El beneficio diferido refleja que en Brasil la deducibilidad de las pérdidas de crédito es posterior a su provisión: con una cartera que crece 37 %, el activo por impuesto diferido subió de US$2.511 millones a US$3.649 millones en seis meses. Es un beneficio real pero de calendario, y su tamaño cae cuando el crecimiento se modera.'),
    P('Esto tiene dos consecuencias para la valoración. Primero, el margen neto de los doce meses (18,65 %) está inflado; el margen antes de impuestos fue 22,7 % en el UDM, 24,5 % en 2025 y 24,3 % en 2024. Las historias parten de un margen neto de 17,5 % (Base) que equivale a un margen antes de impuestos de unos 23,6 % con una tasa efectiva de 26 %. '
      'Segundo, la Ley Complementaria 224/2025 de Brasil eleva la contribución social sobre el lucro (CSLL): para instituciones de pago pasa de 9 % a 12 % en 2026-2027 y a 15 % desde 2028; para sociedades de crédito de 17,5 % a 20 % desde 2028. Es un viento en contra fiscal ya promulgado que justifica no suponer una tasa efectiva baja de forma permanente.'),
    P('El ROE trimestral fue 33 % en el 2T26 y 29,4 % sobre el patrimonio medio de los doce meses; sobre patrimonio final fue 27,2 %. Parte de ese ROE se explica por la tasa efectiva baja. El balance tiene US$82.753 millones de activos (US$74.894 millones al cierre de 2025), financiados con US$45.328 millones de depósitos, US$15.542 millones por pagar a la red de tarjetas, US$4.682 millones de préstamos y financiación y US$13.252 millones de patrimonio total.'))

cap('7. Drivers de crecimiento, márgenes e hipótesis A-1.2',
    P('El modelo proyecta cuatro variables por año e historia: crecimiento de ingresos, margen neto, ROE (que fija el patrimonio requerido) y Ke. No proyecta cartera, depósitos ni morosidad por separado; esas variables se usan como evidencia para fijar las trayectorias y son el objeto de las señales de refutación del capítulo 11. '
      f'En la Base, los ingresos crecen 30 %, 24 %, 20 %, 17 % y 15 % los primeros cinco años y 13 %, 11 %, 9 %, 7,5 % y 6 % después; el margen neto sube de 17,5 % a 19,5 % en el quinto año y se erosiona a 18,5 % por competencia y normalización del costo de crédito. El resultado es una utilidad de {n(PROY[0]["utilidad"])} millones en el año 1 y {n(PROY[-1]["utilidad"])} millones en el año 10.'),
    P(f'Justificación del año 1: el ingreso NIIF del 2T26 fue US$5.513 millones; anualizado (US$22.053 millones) ya supera en 14 % el UDM de US$19.340 millones, de modo que un crecimiento de 30 % sobre el UDM (US$25.141 millones) equivale a un 14 % sobre el ritmo del segundo trimestre. '
      'La Conservadora crece 20 % el primer año por una desaceleración de la cartera y el costo de crédito; la Optimista 36 %, apoyada en México y en la monetización de segmentos de ingresos altos.'),
    P('Márgenes. El margen neto de 2025 fue 18,2 % y el antes de impuestos 24,5 %. En la Base el margen antes de impuestos llega a unos 26 % en el quinto año (eficiencia y escala), y a 25 % al final (competencia y mezcla). La Conservadora mantiene el margen neto en 15,5 % y lo reduce a 14 %; la Optimista lo lleva a 21,5 %; la Disrupción lo comprime a 9 % por pérdidas de crédito y presión de precios. '
      'Cada riesgo va en un solo lugar: el riesgo de crédito está en el margen; el riesgo país y de tasa está en el Ke; el riesgo de ventaja competitiva está en las probabilidades y en la Disrupción.'),
    P('Año terminal. El crecimiento terminal es 4 % (con techo en la tasa libre de 4,94 %) y el ROE terminal depende de la historia: 16 % Base, 12,5 % Conservadora, 20 % Optimista y el costo del patrimonio en la Disrupción (sin ventaja residual). El flujo terminal es la utilidad del año 10 por (1+g) por (1 − g/ROE terminal): cuanto menor el ROE, más patrimonio debe retenerse para sostener el crecimiento.'))

cap('8. Reinversión, capital regulatorio y retorno sobre el patrimonio',
    P('La «reinversión» de un banco es el patrimonio que debe retenerse para sostener el crecimiento de activos ponderados por riesgo. El modelo la aproxima como patrimonio requerido = utilidad ÷ ROE, y el flujo al accionista (FCFE) es la utilidad menos el aumento de ese patrimonio. '
      'No suma depósitos ni inversiones al flujo: la variación de cartera y depósitos es financiación operativa del negocio, no distribución al accionista.'),
    P('Capital regulatorio observado (6-K 2T26, nota de gestión de capital): el conglomerado prudencial de Brasil tiene activos ponderados por riesgo de US$35.710 millones, capital regulatorio de US$5.598 millones, CET1 de US$4.263 millones, índice CET1 de 11,9 % (13,0 % a diciembre de 2025) y capital total de 15,7 % (16,6 %), con un exceso sobre el mínimo requerido de US$1.848 millones. '
      'México reporta capital regulatorio de US$427,6 millones e índice de 14,9 % (mínimo 10,5 %) y Colombia US$179,7 millones e índice de 15,3 % (mínimo 10,5 %). El índice CET1 de Brasil cayó de 13,0 % a 11,9 % en seis meses mientras el APR pasó de US$31.142 millones a US$35.710 millones: es compatible con que el crecimiento de la cartera consuma capital en esa entidad más rápido de lo que lo genera, aunque el 6-K no desglosa la causa (distribuciones a la matriz, deducciones u otras).'),
    P(f'<strong>Control de capital (reserva material).</strong> Se aproximó el APR total como el de Brasil más los de México y Colombia derivados de sus índices (unos US$39.755 millones) y se le hizo crecer al ritmo de los ingresos Base. Con un índice objetivo de 15 %, el capital necesario pasaría de US${n(CAP[0]["capitalObjetivo"])} millones en el año 1 a US${n(CAP[-1]["capitalObjetivo"])} millones en el año 10, mientras que el patrimonio que exige la trayectoria de ROE sería US${n(CAP[0]["patrimonioROE"])} millones y US${n(CAP[-1]["patrimonioROE"])} millones: '
      f'patrimonio/APR sube de {pc(CAP[0]["patrimonioSobreAPR"], 0)} a {pc(CAP[-1]["patrimonioSobreAPR"], 0)}. En palabras sencillas, la trayectoria de ROE decreciente de la Base retiene mucho más capital del que exigiría el regulador. '
      f'Si en lugar del ROE el patrimonio se fijara en 25 %, 30 %, 35 % o 40 % del APR, el valor por acción sería {usd(ALT["valor"][0])}, {usd(ALT["valor"][1])}, {usd(ALT["valor"][2])} y {usd(ALT["valor"][3])}, respectivamente.'),
    P('Por qué la Base no adopta esa alternativa: (a) el APR aproximado por ingresos es burdo, porque los ingresos crecen más rápido que la cartera y porque la mezcla hacia México (con razón de préstamos a depósitos de 35 %) y productos con garantía cambia la densidad de APR; '
      '(b) el patrimonio contable incluye impuestos diferidos activos (US$3.649 millones), plusvalía (US$409 millones) e intangibles (US$747 millones), que en general no cuentan como CET1; (c) la historia de Nu es de retención de capital (nunca ha pagado dividendos) y la regulación de Brasil ha endurecido la tributación del sector. '
      'La decisión de fondo —cuánto del exceso de capital llegará realmente al accionista— queda marcada como el punto principal para la auditoría económica.'))

cap('9. Accionistas, dilución, recompras y gobierno',
    P('Nu Holdings es una sociedad de las Islas Caimán con acciones ordinarias Clase A (cotizan en NYSE) y Clase B. A 31 de diciembre de 2025 había 3.833.072.934 acciones Clase A y 1.022.600.698 Clase B en circulación; los derechos económicos de ambas clases son equivalentes uno a uno, de modo que el modelo trata el total como una sola clase. '
      'El 30 de junio de 2026 las acciones en circulación eran 4.830,7 millones, después de recomprar 40,66 millones de acciones por US$500,4 millones dentro del programa de US$1.000 millones autorizado el 4 de junio de 2026 y vigente hasta el 3 de junio de 2027.'),
    P('La valoración divide por 4.908,8 millones de acciones, que es el promedio ponderado diluido del primer semestre de 2026 (4.904,8 millones en el 2T26). El gasto en acciones permanece dentro de la utilidad; no se resta de nuevo el valor de opciones. La recompra no se suma al FCFE porque ya está incluida en el concepto de flujo distribuible; '
      'sumarla duplicaría el rendimiento del accionista.'),
    P('Nu declara no haber pagado nunca dividendos y no tener política de dividendos. El FCFE del modelo es, por tanto, capacidad de distribución y no una distribución observada. El gobierno corporativo está concentrado en el fundador, David Vélez, presidente y director ejecutivo global, quien asumió de forma interina la supervisión de las plataformas globales tras la renuncia del director de tecnología, Eric Young, anunciada el 23 de octubre de 2026 (permanece hasta el 12 de noviembre). '
      'La compañía afirma que sus prioridades estratégicas no cambian; es un dato de gobierno y ejecución que se sigue en el capítulo 14.'))

