def nivel1_html():
    nav = ''.join(f'<li><a href="#jmr-n1-chapter-{i+1}">{t}</a></li>' for i, (t, _) in enumerate(CAPS))
    sec = ''.join(f'<section id="jmr-n1-chapter-{i+1}"><h2>{t}</h2>{b}</section>' for i, (t, b) in enumerate(CAPS))
    cab = (f'<header><h1>Nu Holdings — análisis fundamental Método JMR A-1.2</h1><p>EN_REVISION. Estados al 30-jun-2026 (6-K 2T26); precio de referencia {usd(precio)} al 30-oct-2026. '
           f'Valor Base {usd(base)}; MOS35 {usd(mos)}. Auditoría económica no realizada; sin QA visual autenticado.</p></header>')
    return f'<article data-jmr-revision="{REV}" data-metodo="A-1.2">{cab}<nav aria-label="Índice del análisis fundamental" data-jmr-n1-standard="14-20261031"><ol>{nav}</ol></nav>{sec}</article>'


if __name__ == '__main__':
    import re
    h = nivel1_html()
    w = len(re.sub(r'<[^>]+>', ' ', h).split())
    print(len(CAPS), 'capítulos', w, 'palabras')
